INSERT INTO "documents" VALUES(1621,'c8d0c0eefe2a0b76b0c928d7fd8b6eb0f3f337f7457762a02fdee4db8df49aea',NULL,NULL,'Kings/Year 12 Mathematics Advanced/Assessment Task 3/SmarterMaths 2021 Advanced Revision Series/ADV-2021HSC-CRS-F1_2.pdf',363819,'other','unknown','inferred',12,'SmarterMaths',2019,'other|2019|smartermaths|unknown','coverpage',8,1,'digital',0,'pre2017','● Graphing absolute value equations is an area that we expect to be tested more regularly in the new course which is reflected in the revision set (last examined in 2019); ● Graph reflections are reviewed; ● Circle functions received a healthy 3-mark allocation in 2020 and are reviewed; ● Proportional (non-linear) relationships are clearly examinable content from Topic Guidance and are covered. Th','excluded','not a question paper','2026-11-10T22:53:15',NULL,NULL,NULL);
