INSERT INTO "figures" VALUES(262,478,NULL,12,'[86, 204, 472, 500]','figures/1628_q13_1.png','tikz/tex/1628_q13_1.tex','graph of two exponential population models','ok','graph','Grid graph: minor lines every 1 year / 10 animals in light grey (0.25pt), major lines black. Curves plotted from the given models y=35(1.055)^x and y=280(0.97)^x, which sit on the crop''s curves (overlay black along both). Remaining blue is minor grid lines that are fainter than the ink threshold in the crop (faint grey grid).',NULL,NULL,NULL);
