INSERT INTO "figures" VALUES(985,1531,NULL,26,'[84, 486, 158, 538]','figures/339_q33_s2.png','tikz/tex/339_q33_s2.tex','solution sketch: right triangle ABH: HB = 1244, angle 19 degrees at A, 71 degrees at H','ok','geometry','Owner note fixed (triangle too small, janky labels): rebuilt from the solution at true shape (right angle at B, 19 deg at A, 71 deg at H, AB = 1244 tan 71) about 2.5x the crop width (rule 22). True arcs centred on A and H ending on both arms, values clear of all lines, clean right-angle box at B, 1244 m centred beside HB, A/B/H in maths italic. Overlay low by design (crop is a tiny handwritten sketch with question text above). Rules 11, 14, 19, 22.',NULL,NULL,NULL);
