INSERT INTO "figures" VALUES(996,1576,NULL,39,'[116, 194, 209, 316]','figures/351_q11_s1.png','tikz/tex/351_q11_s1.tex','solution sketch: graph of y=2*sqrt(16-x^2) on a grid, an arch from x=-4 to x=4 with maximum 8','ok','graph','SOURCE SKETCH IS WRONG: it shows the parabola y=16-x^2 (peak 16), but y=2sqrt(16-x^2) is the upper half of an ellipse with endpoints (-4,0), (4,0) and maximum (0,8), matching the solution (domain [-4,4], range [0,8]). Kept the source grid frame and drew the correct semi-ellipse from the equation; now labels (-4,0), (4,0), (0,8) with dots and the equation, so the domain and range are visible. Low overlay is the different (correct) curve. Rules 9,10,16,18.',NULL,NULL,NULL);
