INSERT INTO "page_reviews" VALUES('q1622',1622,NULL,'approved','Auto-cleared by Claude 12 Nov: Solution is correct: tan x = -1/sqrt3, so x = 5pi/6 and 11pi/6. cos x = 0 gives no solutions.',NULL,NULL,NULL,'claude (owner said yes 12 Nov to auto-clearing Check)','2026-11-12T12:35:00Z','{"at": "2026-11-12T12:35:00Z", "auto_clear": true, "by": "claude (owner said yes 12 Nov to auto-clearing Check)", "note": "Auto-cleared by Claude 12 Nov: Solution is correct: tan x = -1/sqrt3, so x = 5pi/6 and 11pi/6. cos x = 0 gives no solutions.", "question_id": 1622, "status": "approved"}');
INSERT INTO "page_reviews" VALUES('q1623',1623,NULL,'approved','Auto-cleared by Claude 12 Nov: Solution is correct: AD = 2h, BD = 2(h+10)/sqrt3, AB = 10sqrt2. The cosine rule gives h^2 - 10h - 50 = 0, so h = 5 + 5sqrt3. The mark split being inferred does not affect correctness.',NULL,'{"355_q16_1": "approved"}',NULL,'claude (owner said yes 12 Nov to auto-clearing Check)','2026-11-12T12:35:00Z','{"at": "2026-11-12T12:35:00Z", "auto_clear": true, "by": "claude (owner said yes 12 Nov to auto-clearing Check)", "fig": {"355_q16_1": "approved"}, "note": "Auto-cleared by Claude 12 Nov: Solution is correct: AD = 2h, BD = 2(h+10)/sqrt3, AB = 10sqrt2. The cosine rule gives h^2 - 10h - 50 = 0, so h = 5 + 5sqrt3. The mark split being inferred does not affect correctness.", "question_id": 1623, "status": "approved"}');
