INSERT INTO "solutions" VALUES(1,NULL,1,'extracted','Since $P(x)=(1-k^2)x^3+(1-k)x^2+x+1$ has degree 2, $k^2=1$ and $k\ne 1$.
INSERT INTO "solutions" VALUES(2,NULL,2,'extracted','$|x^2-1|=1$ for $x^2=0$ or $x^2=2$.
INSERT INTO "solutions" VALUES(3,NULL,3,'extracted','$f(g(x))=\sqrt{4-x^2}$, with domain given by $x^2\le 4$.
INSERT INTO "solutions" VALUES(4,NULL,4,'extracted','$$\begin{aligned} P(A\cup B)&=P(A)+P(B)-P(A\cap B)\\ &=P(A)+P(B)-P(A\,|\,B)P(B)\\ &=0.4+0.5-0.2\times 0.5\\ &=0.8\end{aligned}$$','1: correct answer',1308,NULL,'parse-v1',NULL,NULL,'[[1, "Correct answer"]]','{}');
INSERT INTO "solutions" VALUES(5,NULL,5,'extracted','$f(x)=4x^2$
INSERT INTO "solutions" VALUES(6,NULL,6,'extracted','$$\begin{aligned} y&=2^{3x}=e^{3x\ln 2}\\ \therefore\ \dfrac{dy}{dx}&=3\ln 2\,e^{3x\ln 2}\\ &=(3\ln 2)2^{3x}\\ &=(\ln 8)2^{3x}\end{aligned}$$','1: correct answer',1308,NULL,'parse-v1',NULL,NULL,'[[1, "Correct answer"]]','{}');
INSERT INTO "solutions" VALUES(7,NULL,7,'extracted','$$\begin{aligned}\bar{x}&=(1\times 2+3\times 4+5\times 6+7\times 8)\div 20\\ &=5\end{aligned}$$','1: correct answer',1308,NULL,'parse-v1',NULL,NULL,'[[1, "Correct answer"]]','{}');
INSERT INTO "solutions" VALUES(8,NULL,8,'extracted','$$\begin{aligned}\int\tan x(\cot x+\tan x)\,dx&=\int(1+\tan^2 x)\,dx\\ &=\int\sec^2 x\,dx\\ &=\tan x+c\end{aligned}$$','1: correct answer',1308,NULL,'parse-v1',NULL,NULL,'[[1, "Correct answer"]]','{}');
INSERT INTO "solutions" VALUES(9,NULL,9,'extracted','$800=P(1+0.005)^{48}$
INSERT INTO "solutions" VALUES(10,NULL,10,'extracted','$$\dfrac{a}{1-r}-\dfrac{a(1-r^n)}{1-r}=2ar^{n-1}$$
INSERT INTO "solutions" VALUES(11,NULL,11,'extracted','Circle has centre $(-2,2)$ and radius is 2.
INSERT INTO "solutions" VALUES(12,NULL,12,'extracted','$$\begin{aligned}Q_1-1.5\times IQR&=11-1.5\times 6\\ &=2\\ &<3\end{aligned}$$
INSERT INTO "solutions" VALUES(13,NULL,13,'extracted','$A(-3,1)$, $B(5,-3)$
INSERT INTO "solutions" VALUES(14,NULL,14,'extracted','$\log_x y=2$, so $y=x^2$.
INSERT INTO "solutions" VALUES(15,NULL,15,'extracted','$\tan^2 x=3$
INSERT INTO "solutions" VALUES(16,16,16,'extracted','\exfigure{1308_q16_s1}
INSERT INTO "solutions" VALUES(17,17,16,'extracted','$$\begin{aligned}AC^2&=6^2+10^2-2\times 6\times 10\cos 120^\circ\\ &=196\end{aligned}$$
