INSERT INTO "tags" VALUES(20522,2332,1380,'2024','Graph transformations','Establish using graphing applications that replacing x by ―x in the equation of a graph corresponds to the reflection of the graph in the y-axis, and that replacing y by ―y corresponds to a reflection in the x-axis','Y11-162',11,'moved_to_year_11',0,0.85,'checker','v2','tag-v2.2');
