INSERT INTO "tags" VALUES(22059,2843,1747,'2024','Introduction to differentiation','Interpret f(x) as increasing at x = c when f''(c)> 0 and decreasing at x = c when f''(c)< 0','Y11-135',11,'moved_to_year_11',1,0.85,'agreed','v2','tag-v2.2');
INSERT INTO "tags" VALUES(22060,2843,1747,'2024','Differential calculus','Apply the rules of differentiation to find the derivative of f(x)= keax, where k and a are constants','Y12-229',12,'examinable',0,0.85,'agreed','v2','tag-v2.2');
