INSERT INTO "tags" VALUES(22063,2844,1747,'2024','Integral calculus','Apply ∫b a f(x) dx = F(b)― F(a), where F(x) is a primitive of f(x), to calculate definite integrals and solve related theoretical problems involving functions within the scope of the Mathematics Advanced course','Y12-275',12,'examinable',1,0.7,'agreed','v2','tag-v2.2');
INSERT INTO "tags" VALUES(22064,2844,1747,'2024','Integral calculus','Establish and use the formula ∫exdx = ex + C','Y12-264',12,'examinable',0,0.7,'agreed','v2','tag-v2.2');
INSERT INTO "tags" VALUES(22065,2844,1747,'2024','Integral calculus','Use the formula ∫xndx = 1 n+1 xn+1 + C for real n ≠―1','Y12-261',12,'examinable',0,0.7,'agreed','v2','tag-v2.2');
