INSERT INTO "tags" VALUES(22484,48,33,'2024','Differential calculus','Apply the product, quotient and chain rules to differentiate functions of the form f(x)g(x), f(x) g(x) or f(g(x)), where f(x) and g(x) are any of the functions within the scope of the Mathematics Advanced course','Y12-240',12,'examinable',1,0.9,'rule-fix','v2','tag-v2.3');
INSERT INTO "tags" VALUES(22485,48,33,'2024','Differential calculus','Use chain rule on the identity eln x = x to prove the formula d dx(ln x)= 1 x for the derivative of the natural logarithm function where x > 0','Y12-233',12,'examinable',0,0.9,'rule-fix','v2','tag-v2.3');
