INSERT INTO "tags" VALUES(22488,119,86,'2024','Differential calculus','Apply the product, quotient and chain rules to differentiate functions of the form f(x)g(x), f(x) g(x) or f(g(x)), where f(x) and g(x) are any of the functions within the scope of the Mathematics Advanced course','Y12-240',12,'examinable',1,0.9,'rule-fix','v2','tag-v2.3');
INSERT INTO "tags" VALUES(22489,119,86,'2024','Differential calculus','Apply the rules of differentiation to find the derivative of f(x)= keax, where k and a are constants','Y12-229',12,'examinable',0,0.9,'rule-fix','v2','tag-v2.3');
INSERT INTO "tags" VALUES(22490,119,86,'2024','Differential calculus','Determine the formulas d dx(sin x)= cos x and d dx(cos x)= ― sin x informally by using the graphs of y = sin x and y = cos x and verify with graphing applications','Y12-236',12,'examinable',0,0.9,'rule-fix','v2','tag-v2.3');
